-- Synchronize source fields that this generated migration explicitly updates.
UPDATE public.source_people source
SET source_person_key = input.source_person_key,
    source_type = 'official_election',
    source_id = 'cec-2024-votedata',
    party = input.party,
    election_year = input.election_year,
    source_payload =
        (CASE
            WHEN input.set_vote_count THEN COALESCE(source.source_payload, '{}'::JSONB) - 'votes'
            ELSE COALESCE(source.source_payload, '{}'::JSONB)
        END)
        || CASE WHEN input.set_candidate_no
            THEN jsonb_build_object('candidateNo', input.candidate_no) ELSE '{}'::JSONB END
        || CASE WHEN input.set_vote_count
            THEN jsonb_build_object('voteCount', input.vote_count) ELSE '{}'::JSONB END
        || CASE WHEN input.set_vote_rate
            THEN jsonb_build_object('voteRate', input.vote_rate) ELSE '{}'::JSONB END
        || CASE WHEN (
            input.set_is_elected
            OR input.set_candidacy_status
            OR input.set_election_result
            OR input.set_registration_status
        ) THEN jsonb_build_object('elected', input.is_elected) ELSE '{}'::JSONB END,
    updated_at = NOW()
FROM _historical_cec_existing_candidate_input_20260730 input
WHERE source.id = input.source_person_id;

